import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 16 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each (147 items total). Passages, prompts,
 * and numbers are distinct from earlier practice tests.
 */

// ─────────────────────── PRACTICE TEST 16 · R&W M1 (27) ──────────────────────
const T16_RW_M1: SatQuestion[] = [
  { id: "t16rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The lecture was so ______ that students who had dreaded the topic left eager to read more about it on their own.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["engaging", "tedious", "incoherent", "brief"], correct: 0, explanation: "The answer is \"engaging.\" The clause \"students who had dreaded the topic left eager to read more\" describes a reversal from dread to enthusiasm, which only a captivating, interest-sparking lecture would produce. \"Tedious\" (boring) would leave students still dreading the topic, the opposite effect. \"Incoherent\" (confusing, disjointed) would frustrate students, not inspire further reading. \"Brief\" merely describes the lecture's length and gives no reason students became eager to learn more." },
  { id: "t16rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee ______ reviewing the budget proposals all afternoon before reaching a decision.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "are", "have been"], correct: 0, explanation: "The answer is \"was.\" This tests subject-verb agreement and verb tense: \"committee\" is a singular collective noun treated as a single unit, and the time marker \"all afternoon before reaching a decision\" places the action in the simple past, so the singular past \"was\" is correct. \"Were\" is the plural past form and disagrees with the singular subject. \"Are\" is plural and present tense, wrong on both number and time. \"Have been\" is present-perfect, implying an action continuing into the present, which clashes with the clearly completed past event." },
  { id: "t16rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Certain desert plants open their pores only at night, taking in carbon dioxide in the cool dark and storing it for daytime photosynthesis, which sharply limits the water they lose to the sun.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["A nighttime gas-exchange strategy lets these plants photosynthesize by day while conserving water.", "These plants cannot photosynthesize at all.", "These plants lose more water than ordinary plants.", "These plants open their pores only during the hottest hours."], correct: 0, explanation: "The passage explains that opening pores at night and storing CO2 reduces daytime water loss while still enabling photosynthesis (choice A). B and C contradict the text, and D reverses the stated nighttime timing." },
  { id: "t16rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail was washed out by the spring floods. ______, the rangers closed it until repairs could be made.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Therefore", "However", "In contrast"], correct: 1, explanation: "The closure is a direct result of the washed-out trail, so a cause-effect transition (\"Therefore\") fits. The other three signal contrast, which the logical sequence does not support." },
  { id: "t16rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The tour visits three capitals ______ Rome, Vienna, and Prague.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["capitals, ", "capitals: ", "capitals; ", "capitals "], correct: 1, explanation: "A colon correctly introduces the list that specifies \"three capitals.\" A comma is too weak to set off the list, a semicolon joins independent clauses, and no punctuation leaves the list unsignaled." },
  { id: "t16rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The committee's report was admirably ______, addressing every objection raised in the public hearings point by point.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["comprehensive", "evasive", "rushed", "vague"], correct: 0, explanation: "Addressing every objection point by point makes the report \"comprehensive.\" \"Evasive\" and \"vague\" mean the opposite, and \"rushed\" describes pace, not the thoroughness the sentence praises." },
  { id: "t16rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is awarded only to writers who have published at least one book and who are under the age of thirty-five.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A thirty-year-old who has published two books may qualify.", "A writer who has never published a book may qualify.", "Any writer over thirty-five may qualify.", "Only writers with no books may qualify."], correct: 0, explanation: "Both conditions — a published book and an age under thirty-five — are met by the thirty-year-old with two books (choice A). B and D ignore the publication rule, and C ignores the age cap." },
  { id: "t16rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum redesigned its exhibits to be more accessible. ______, it added audio guides in six languages.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "For example", "Otherwise", "Instead"], correct: 1, explanation: "The audio guides are a concrete illustration of the accessibility redesign, so \"For example\" fits. The other options signal contrast or substitution, which the supporting detail does not require." },
  { id: "t16rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the memoir refreshingly ______, free of the self-flattery that fills so many accounts by public figures.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["candid", "boastful", "guarded", "dull"], correct: 0, explanation: "Being free of self-flattery means the memoir is \"candid\" (frankly honest). \"Boastful\" is the very fault it avoids, while \"guarded\" and \"dull\" do not match \"refreshingly.\"" },
  { id: "t16rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Honeybees communicate the location of food by performing a looping \"waggle dance\" whose angle and duration encode the direction and distance other bees must fly.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Honeybees use a dance to tell hive-mates where food is located.", "Honeybees cannot share information with one another.", "Honeybees fly in random directions to find food.", "The waggle dance has no meaning."], correct: 0, explanation: "The dance's angle and duration encode direction and distance to food, so it communicates location (choice A). B, C, and D each contradict the passage's central claim." },
  { id: "t16rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the coach nor the players ______ satisfied with the referee's final call.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "In a \"neither…nor\" subject, the verb agrees with the nearer noun, here the plural \"players,\" so \"were\" is correct. The singular forms in the other choices fail to match \"players.\"" },
  { id: "t16rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The new bridge cost far more than planned. ______, it cut the average commute across the river nearly in half.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "A high cost paired with a clear benefit is a contrast, so \"Still\" fits. \"Therefore\" implies cause-effect, \"For instance\" introduces an example, and \"In short\" summarizes — none captures the concession." },
  { id: "t16rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Average rainfall measured 22 inches in the eastern county, 31 inches in the central county, and 18 inches in the western county last year.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The western county received the least rainfall.", "The eastern county received the most rainfall.", "The central county received the least rainfall.", "All three counties received equal rainfall."], correct: 0, explanation: "At 18 inches, the western county's total is the smallest of the three (choice A). The eastern figure (22) is not the largest, the central figure (31) is the largest not the least, and the totals are unequal." },
  { id: "t16rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The scientist published a study ______ overturned a long-held assumption about coral growth.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["that", "what", "where", "and it"], correct: 0, explanation: "The relative pronoun \"that\" introduces the clause modifying \"study.\" \"What\" cannot follow a noun antecedent, \"where\" marks a place, and \"and it\" creates a comma-splice-style fault." },
  { id: "t16rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Rushing to catch the train, ______ the briefcase was left behind on the platform bench.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["rushing to catch the train, the briefcase was left behind", "the traveler, rushing to catch the train, left the briefcase behind", "the platform bench held the briefcase, rushing to catch the train", "left behind, the train was caught by the briefcase"], correct: 1, explanation: "The modifier \"rushing to catch the train\" must describe a person, and only choice B places \"the traveler\" right after it. The others leave the briefcase or bench illogically doing the rushing." },
  { id: "t16rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist argues that offering free public transit increases overall productivity because workers spend less time and money commuting.", prompt: "Which finding, if true, would most strengthen the economist's claim?", type: "mcq", choices: ["Cities that made transit free saw measurable gains in worker output.", "Free transit is popular among residents.", "Building new transit lines is expensive.", "Most commuters already own cars."], correct: 0, explanation: "Measured output gains in cities with free transit directly support the productivity claim (choice A). Popularity (B), construction cost (C), and car ownership (D) say nothing about productivity." },
  { id: "t16rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with the lead actors, ______ planning a surprise for opening night.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "The subject is the singular \"director\"; a \"together with\" phrase does not change the verb's number, so \"is\" is correct. The plural forms wrongly agree with \"actors\" inside the interrupting phrase." },
  { id: "t16rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to stress that an unexpected result held up under repeated testing. ______, the effect appeared in all five follow-up trials.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Indeed", "However", "Otherwise"], correct: 1, explanation: "\"Indeed\" intensifies the point that the result was reliable, matching evidence from all five trials. The contrast words (\"By contrast,\" \"However\") and \"Otherwise\" would undercut rather than reinforce the claim." },
  { id: "t16rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The novel's narrator is deliberately ______: readers can never be sure whether his confident account of events should be trusted.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unreliable", "omniscient", "transparent", "honest"], correct: 0, explanation: "A narrator readers cannot trust is \"unreliable.\" \"Honest\" and \"transparent\" imply trustworthiness, and \"omniscient\" refers to knowledge, not credibility." },
  { id: "t16rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The scholarship is open only to students who major in engineering and who maintain a grade average above 3.5.", prompt: "Which student clearly qualifies for the scholarship?", type: "mcq", choices: ["An engineering major with a 3.8 average.", "A history major with a 3.9 average.", "An engineering major with a 3.0 average.", "A student with no declared major."], correct: 0, explanation: "Both conditions — engineering major and an average above 3.5 — are satisfied only by choice A. B fails the major requirement, C fails the grade requirement, and D fails both." },
  { id: "t16rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the engine ______ they refueled the aircraft for its next flight.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["engine, and then", "engine and, then", "engine then", "engine, then"], correct: 0, explanation: "Two independent clauses must be joined by a comma plus the coordinating conjunction \"and,\" giving \"engine, and then.\" The other options drop the conjunction or misplace the comma, creating fragments or splices." },
  { id: "t16rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although famous for his ______ public speeches, the philosopher wrote private letters that were warm and almost playful.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["austere", "tender", "casual", "humorous"], correct: 0, explanation: "The contrast with \"warm and almost playful\" letters implies the speeches were \"austere\" (severe and plain). \"Tender,\" \"casual,\" and \"humorous\" would not contrast with the playful letters." },
  { id: "t16rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A geographer notes that coastal cities founded near natural harbors grew into major trade hubs faster than inland settlements, crediting the ease of shipping goods by sea.", prompt: "Which choice best describes the geographer's explanation?", type: "mcq", choices: ["Harbor access made sea shipping easy, speeding the growth of coastal cities.", "Inland settlements had better access to shipping.", "Natural harbors slowed the growth of nearby cities.", "City location had no effect on trade."], correct: 0, explanation: "The geographer credits faster growth to harbor-enabled sea shipping (choice A). B reverses the advantage, C contradicts \"grew…faster,\" and D denies the stated relationship." },
  { id: "t16rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The library extended its hours ______ many students had asked for more time to study before exams.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["hours because", "hours, because", "hours; because", "hours: because"], correct: 0, explanation: "When a \"because\" clause follows the main clause and is essential, no punctuation is needed before it, so \"hours because\" is correct. A semicolon or colon would wrongly break the connected clause." },
  { id: "t16rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The company switched its delivery fleet to electric vehicles. ______, it lowered its fuel costs and its carbon emissions at once.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "Lower fuel costs and emissions follow directly from the switch, so the cause-effect transition \"As a result\" fits. The remaining choices signal contrast or illustration, which the sentence's logic does not call for." },
  { id: "t16rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach offered ______ feedback, pointing out exactly which footwork drill each player should practice next.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "general", "vague", "harsh"], correct: 0, explanation: "Pointing out exactly which drill makes the feedback \"specific.\" \"General\" and \"vague\" are opposites, and \"harsh\" describes tone, not the precision the sentence emphasizes." },
  { id: "t16rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "After beavers returned to the stream, their dams slowed the current, which let sediment settle and created wetland pools that, in turn, drew back frogs and wading birds that had long been absent.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Returning beavers set off a chain of changes that revived wetland wildlife.", "Beavers drove away all wildlife from the stream.", "The dams sped up the stream's current.", "Frogs and birds had always lived at the stream."], correct: 0, explanation: "The beavers' dams slowed the current, formed pools, and drew back absent species — a chain of effects reviving wildlife (choice A). B, C, and D each contradict a specific detail in the passage." },
];

// ─────────────────────── PRACTICE TEST 16 · R&W M2 easy (27) ─────────────────
const T16_RW_M2E: SatQuestion[] = [
  { id: "t16rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was too ______ to carry, so she took out half of her books.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "empty", "small"], correct: 0, explanation: "The answer is \"heavy.\" The clue \"too ______ to carry, so she took out half of her books\" shows weight was the problem, and removing books lightens a heavy load. \"Light\" is the opposite — a light backpack carries easily, giving no reason to remove anything. \"Empty\" contradicts the fact that it still held books to take out. \"Small\" describes size, but a small pack would not be hard to carry, so it does not fit the weight clue." },
  { id: "t16rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The answer is \"are.\" Subject-verb agreement requires a plural verb for the plural subject \"three puppies,\" and \"are\" is the plural present-tense form that pairs with \"playing.\" \"Is\" is singular present and cannot follow a plural subject. \"Was\" is singular past, wrong in both number and tense for an ongoing action. \"Am\" is the first-person singular form used only with \"I,\" so it cannot match \"puppies.\"" },
  { id: "t16rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bats are not blind; they use sound that bounces off objects to find their way and catch insects in the dark.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bats use bouncing sound to navigate and hunt in the dark.", "Bats cannot move at night.", "Bats are completely blind.", "Bats never eat insects."], correct: 0, explanation: "The answer is \"Bats use bouncing sound to navigate and hunt in the dark,\" which restates the passage's claim that bats \"use sound that bounces off objects to find their way and catch insects in the dark.\" \"Bats cannot move at night\" contradicts \"find their way,\" which shows they do move. \"Bats are completely blind\" directly contradicts the opening clause \"Bats are not blind.\" \"Bats never eat insects\" contradicts \"catch insects in the dark.\"" },
  { id: "t16rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "It began to rain hard. ______, we moved the picnic inside.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The answer is \"So.\" The hard rain is the cause and moving the picnic inside is its result, so the cause-effect connector \"So\" matches the logic. \"For example\" would signal that moving inside illustrates the rain, but it is a consequence, not an example. \"However\" signals contrast, yet the two sentences agree rather than oppose. \"Meanwhile\" marks simultaneous events, but the rain leads to the move rather than merely happening alongside it." },
  { id: "t16rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night we ______ dinner at my grandmother's house.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["eat", "eats", "ate", "eating"], correct: 2, explanation: "The answer is \"ate.\" The time marker \"Last night\" signals completed past action, and \"ate\" is the simple past tense of \"eat,\" which also agrees with the subject \"we.\" \"Eat\" is present tense and clashes with \"last night.\" \"Eats\" is the third-person singular present form, wrong in both tense and number for \"we.\" \"Eating\" is a participle that needs a helping verb (such as \"were\") and cannot serve as the main verb on its own." },
  { id: "t16rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The puzzle was very ______, so it took us all weekend to finish.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["difficult", "simple", "small", "colorful"], correct: 0, explanation: "The answer is \"difficult.\" The clue \"so it took us all weekend to finish\" shows the puzzle resisted quick solving, which a difficult puzzle does. \"Simple\" is the opposite — a simple puzzle would be finished fast, not over a whole weekend. \"Small\" describes size and would suggest a quick job, not a long one. \"Colorful\" describes appearance and has no bearing on how long the puzzle took." },
  { id: "t16rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives you exercise, and produces no pollution.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is harmful.", "Walking to school costs a lot of money.", "Walking to school causes pollution."], correct: 0, explanation: "The answer is \"Walking to school has several benefits.\" The sentence names three advantages — it \"saves money, gives you exercise, and produces no pollution\" — which \"several benefits\" accurately summarizes. \"Walking to school is harmful\" contradicts the positive list. \"Walking to school costs a lot of money\" contradicts \"saves money.\" \"Walking to school causes pollution\" contradicts \"produces no pollution.\"" },
  { id: "t16rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "We waited nearly ______ hour for the doctor.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Hour\" begins with a silent h, making a vowel sound, so \"an\" is correct. \"A\" precedes consonant sounds, and \"the only\" and \"some\" change the meaning." },
  { id: "t16rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The water in the lake was so ______ that we could see the rocks at the bottom.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "muddy", "deep", "cold"], correct: 0, explanation: "Seeing the bottom means the water was \"clear.\" \"Muddy\" would hide the rocks, and \"deep\" or \"cold\" do not explain the visibility." },
  { id: "t16rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My sister and I ______ baking cookies this afternoon.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "The compound subject \"my sister and I\" is plural, so \"are\" is correct. \"Is,\" \"was,\" and \"am\" are singular forms that do not agree." },
  { id: "t16rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Trees take in carbon dioxide and release oxygen, which helps keep the air clean for people and animals.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Trees help clean the air by exchanging gases.", "Trees release carbon dioxide into the air.", "Trees make the air dirty.", "Trees have no effect on the air."], correct: 0, explanation: "The passage says trees take in carbon dioxide and release oxygen, helping clean the air (choice A). B reverses the gases, and C and D contradict the text." },
  { id: "t16rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, we lit candles and waited it out.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "So", "For example", "Instead"], correct: 1, explanation: "Lighting candles is the response to losing power, so \"So\" shows the result. \"However\" and \"Instead\" signal contrast, and \"For example\" introduces an illustration." },
  { id: "t16rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday the chef ______ a new dessert for the menu.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["create", "creates", "created", "creating"], correct: 2, explanation: "\"Yesterday\" requires the past tense \"created.\" \"Create\" and \"creates\" are present tense, and \"creating\" cannot serve as the main verb alone." },
  { id: "t16rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After the long hike, the campers were ______ and fell asleep quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "excited", "hungry", "curious"], correct: 0, explanation: "Falling asleep quickly after a long hike shows the campers were \"tired.\" \"Excited\" and \"curious\" would keep them awake, and \"hungry\" does not explain the sleep." },
  { id: "t16rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The bakery opens at 7 a.m. on weekdays but does not open until 9 a.m. on Saturdays.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The bakery opens later on Saturdays than on weekdays.", "The bakery never opens on weekdays.", "The bakery opens at midnight on Saturdays.", "The bakery is closed every Saturday."], correct: 0, explanation: "Opening at 9 a.m. on Saturday is later than the 7 a.m. weekday opening (choice A). B, C, and D each contradict the stated hours." },
  { id: "t16rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The bird built ______ nest in the old oak tree.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "The singular possessive \"its\" matches the singular \"bird.\" \"It's\" means \"it is,\" \"their\" is plural, and \"they're\" means \"they are.\"" },
  { id: "t16rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals sleep through the winter. ______, bears spend the cold months in a deep rest.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "Bears are an example of an animal that sleeps through winter, so \"For example\" fits. The other choices signal contrast or substitution, which the supporting example does not need." },
  { id: "t16rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The street was very ______, so we had to shout to hear each other.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["noisy", "quiet", "empty", "narrow"], correct: 0, explanation: "Having to shout means the street was \"noisy.\" \"Quiet\" and \"empty\" would not force shouting, and \"narrow\" describes width, not sound." },
  { id: "t16rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The keys ______ on the kitchen counter where I left them.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Keys\" is plural, so the plural verb \"are\" is correct. \"Is,\" \"was,\" and \"am\" are singular and do not agree." },
  { id: "t16rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Some lizards can drop their tails to escape a predator, and the tail later grows back.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Some lizards can lose and regrow their tails.", "Lizards cannot escape predators.", "Lizards never lose their tails.", "A lizard's tail never grows back."], correct: 0, explanation: "The passage says lizards drop their tails to escape and the tail grows back (choice A). B, C, and D each contradict the text." },
  { id: "t16rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to hike the long trail. ______, the rain forced us to take the short one.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "Planning one trail but taking another is a contrast, so \"However\" fits. \"Therefore\" and \"Similarly\" do not show contrast, and \"For example\" introduces an illustration." },
  { id: "t16rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month our class ______ to perform a short play.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The singular collective noun \"class\" takes \"plans,\" and the present tense suits the upcoming \"next month\" event. \"Plan\" is plural, \"planned\" is past, and \"planning\" cannot stand alone." },
  { id: "t16rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new tablet is very ______; it can run for two days on a single charge.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["efficient", "fragile", "expensive", "heavy"], correct: 0, explanation: "Running two days on one charge shows the tablet is \"efficient.\" \"Fragile,\" \"expensive,\" and \"heavy\" do not describe long battery life." },
  { id: "t16rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Stretching before exercise warms up the muscles, improves flexibility, and lowers the risk of injury.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Stretching before exercise provides several benefits.", "Stretching causes more injuries.", "Stretching makes muscles colder.", "Stretching should never be done."], correct: 0, explanation: "The sentence lists three benefits of stretching (choice A). B, C, and D each contradict the stated advantages." },
  { id: "t16rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She picked ______ apple from the basket on the table.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Apple\" begins with a vowel sound, so \"an\" is correct. \"A\" precedes consonant sounds, and \"the only\" and \"some\" alter the meaning." },
  { id: "t16rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The directions were easy to follow. ______, the bookshelf went together in under an hour.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "However", "Instead", "Otherwise"], correct: 0, explanation: "Quick assembly is the result of easy directions, so \"As a result\" fits. \"However\" and \"Instead\" signal contrast, and \"Otherwise\" suggests an alternative outcome." },
  { id: "t16rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience grew ______ as the magician revealed his final, surprising trick.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "sleepy", "angry"], correct: 0, explanation: "A surprising final trick leaves the audience \"amazed.\" \"Bored\" and \"sleepy\" are opposite reactions, and \"angry\" does not fit a delightful surprise." },
];

// ─────────────────────── PRACTICE TEST 16 · R&W M2 hard (27) ─────────────────
const T16_RW_M2H: SatQuestion[] = [
  { id: "t16rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The candidate's statement was carefully ______, praising the plan's goals while committing to none of its actual provisions.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["noncommittal", "decisive", "blunt", "enthusiastic"], correct: 0, explanation: "Praising goals while committing to nothing is \"noncommittal.\" \"Decisive\" and \"blunt\" imply taking a clear stand, and \"enthusiastic\" overstates the guarded tone." },
  { id: "t16rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The article first lays out the conventional explanation in detail, then devotes its remaining pages to dismantling that explanation point by point.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It presents an accepted view and then systematically argues against it.", "It defends the conventional view throughout.", "It lists unrelated facts with no argument.", "It repeats a single example without analysis."], correct: 0, explanation: "Laying out a view and then dismantling it point by point is a present-then-refute structure (choice A). B reverses the author's stance, and C and D ignore the dismantling argument." },
  { id: "t16rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A coating retained 95% of its shine after 1 year, 93% after 2 years, and 70% after 5 years of outdoor exposure.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Shine declined far more steeply between years 2 and 5 than in the first two years.", "Shine increased over time.", "Shine stayed perfectly constant.", "The coating had no shine left after 2 years."], correct: 0, explanation: "Losing 2 points over 2 years is gentle, but losing 23 points over the next 3 years is much steeper per year (choice A). B and C contradict the falling figures, and D misreads the 93% at year 2." },
  { id: "t16rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The medication relieved the patients' symptoms quickly. ______, it produced side effects severe enough that a third of them stopped taking it.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "A benefit followed by a serious drawback is a contrast, so \"However\" fits. \"Therefore,\" \"Likewise,\" and \"Accordingly\" all imply agreement or consequence, not opposition." },
  { id: "t16rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship teaches students to analyze data, to write reports, and ______ their findings to clients.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel structure with \"to analyze\" and \"to write\" requires the infinitive \"to present.\" The gerund and bare or past forms break the parallel series." },
  { id: "t16rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The history refuses to ______ its central figure, presenting his cruelties as plainly as his reforms.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sanitize", "condemn", "describe", "recall"], correct: 0, explanation: "Showing cruelties plainly means the book refuses to \"sanitize\" (clean up) its subject. \"Condemn\" is the opposite of flattering, and \"describe\" and \"recall\" lack the favorable-cleanup sense being rejected." },
  { id: "t16rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the earlier model treated emotions as obstacles to clear thinking, the newer account holds that emotions guide attention toward what matters and so aid reasoning.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older view of emotion with a newer, more favorable one.", "To prove emotions always cloud judgment.", "To summarize only the earlier model.", "To argue that reasoning is impossible."], correct: 0, explanation: "\"Where the earlier…the newer…\" contrasts a negative view of emotion with a positive one (choice A). B states the older view as fact, C ignores the newer account, and D is unsupported." },
  { id: "t16rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The first prototype passed every safety test ______ the second prototype failed three of them on the first day.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["test, the", "test; the", "test the", "test: the"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone makes a splice, no punctuation runs them together, and a colon does not fit two equal contrasting clauses." },
  { id: "t16rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the lecture rewarded close attention, packing several intricate arguments into every few minutes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["simplistic", "demanding", "dense", "rigorous"], correct: 0, explanation: "\"Far from\" signals an opposite, and a lecture packed with intricate arguments is the opposite of \"simplistic.\" \"Demanding,\" \"dense,\" and \"rigorous\" all match the lecture rather than oppose it." },
  { id: "t16rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Supporters insist the new schedule reduced worker fatigue without cutting output. Yet in the quarter it took effect, the factory's production fell by 6%.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It introduces evidence that complicates the supporters' claim.", "It restates the supporters' claim exactly.", "It confirms that output was unaffected.", "It proposes a different schedule."], correct: 0, explanation: "A 6% drop in production complicates the claim that output was not cut (choice A). B and C ignore the contradiction, and D proposes nothing new." },
  { id: "t16rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The recipe demands three rare ingredients ______ saffron, truffle, and aged vinegar.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["ingredients,", "ingredients:", "ingredients;", "ingredients"], correct: 1, explanation: "A colon introduces the list specifying the \"three rare ingredients.\" A comma is too weak, a semicolon joins clauses, and no punctuation leaves the list unsignaled." },
  { id: "t16rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The telescope captured the comet's approach in stunning detail. ______, clouds rolled in before it could record the closest pass.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Unfortunately", "Therefore", "Likewise"], correct: 1, explanation: "A success undone by bad luck calls for \"Unfortunately.\" \"Indeed\" and \"Likewise\" reinforce rather than contrast, and \"Therefore\" implies the clouds resulted from the success." },
  { id: "t16rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, students who used the new study app scored 15% higher on the final exam, but they also reported spending 25% more time studying.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The app users scored higher but also studied more.", "The app users scored higher while studying less.", "The app had no effect on scores.", "Non-users scored higher than app users."], correct: 0, explanation: "App users scored 15% higher and reported 25% more study time, so both rose (choice A). B reverses the time finding, and C and D contradict the score gain." },
  { id: "t16rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The sculpture that stands beside the fountains ______ to a sculptor whose later works fill the city's museums.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["belong", "belongs", "belonging", "to belong"], correct: 1, explanation: "The singular subject \"sculpture\" (not the plural \"fountains\" in the modifier) takes the singular verb \"belongs.\" The plural, participial, and infinitive forms fail subject-verb agreement." },
  { id: "t16rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor was prized for her ______ — for cutting every sentence that did not earn its place on the page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["rigor", "leniency", "hesitation", "warmth"], correct: 0, explanation: "Cutting every unearned sentence reflects exacting \"rigor.\" \"Leniency\" is the opposite, and \"hesitation\" and \"warmth\" do not describe demanding strictness." },
  { id: "t16rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author begins by admitting that the early printing press was crude and slow, then argues that these very flaws pushed inventors toward the refinements that made printing fast and cheap.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It reframes early shortcomings as the spur for later improvements.", "It denies the early press had any flaws.", "It claims printing never improved.", "It lists the prices of printed books."], correct: 0, explanation: "The crude, slow flaws are recast as the spur for refinements (choice A). B contradicts the admitted flaws, C contradicts \"made printing fast and cheap,\" and D is off topic." },
  { id: "t16rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having studied the river for a decade ______ the scientist could predict the timing of each year's flood almost to the day.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the timing of each year's flood was predictable", "the scientist could predict the timing of each year's flood", "predicting the flood was easy each year", "it became easy to predict the flood's timing"], correct: 1, explanation: "The modifier \"having studied the river\" must describe a person, and only choice B places \"the scientist\" right after it. The others let an abstract idea do the studying." },
  { id: "t16rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine produced strong immunity in laboratory mice. ______, the response in human volunteers proved weaker and shorter-lived.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In human trials, however", "For this reason", "Similarly"], correct: 1, explanation: "The contrast between strong results in mice and weak results in people is best signaled by \"In human trials, however.\" \"Consequently,\" \"For this reason,\" and \"Similarly\" imply agreement, not contrast." },
  { id: "t16rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, in which a quiet opening motif returns, fully transformed, in the triumphant finale.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "fragmented", "arbitrary", "monotonous"], correct: 0, explanation: "A motif that returns transformed to tie the work together gives it a \"cohesive\" design. \"Fragmented\" and \"arbitrary\" suggest disorder, and \"monotonous\" implies dull sameness." },
  { id: "t16rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across six schools, those that added a free breakfast program saw attendance rise by an average of 9%, while schools without the program saw no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding free breakfast was associated with higher attendance.", "Free breakfast lowered attendance.", "School policy had no relationship to attendance.", "Every school added the breakfast program."], correct: 0, explanation: "Schools with the program saw a 9% attendance rise while others saw none (choice A). B reverses the effect, C denies the relationship, and D overgeneralizes." },
  { id: "t16rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The composer's early sketches — hurried, fragmentary, but unmistakably original ______ already hint at the masterpieces to come.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["original —", "original,", "original", "original;"], correct: 0, explanation: "A pair of dashes sets off the interrupting description, so the second dash must close it. A comma, no punctuation, or a semicolon would not match the opening dash." },
  { id: "t16rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The board dismissed the engineer's caution as ______, only to see the very failure she had warned of strike within the year.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overcautious", "prophetic", "justified", "sensible"], correct: 0, explanation: "Wrongly dismissing a warning that then comes true means they judged it \"overcautious.\" \"Prophetic,\" \"justified,\" and \"sensible\" would all credit the warning rather than dismiss it." },
  { id: "t16rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One critic blames the film's failure on its confusing plot; another blames its weak marketing. A third suggests that the two problems fed each other.", prompt: "Which choice best describes the third critic's position?", type: "mcq", choices: ["The plot and marketing problems worked together to cause the failure.", "Neither the plot nor the marketing mattered.", "Only the plot was to blame.", "The film did not actually fail."], correct: 0, explanation: "The third critic says the two problems \"fed each other\" (choice A). B denies both causes, C names only one, and D contradicts the premise of failure." },
  { id: "t16rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The pilots rerouted the flight ______ a sudden storm had closed the original airport.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["flight, a", "flight; a", "flight a", "flight: a"], correct: 1, explanation: "Two independent clauses are correctly joined by a semicolon. A comma alone makes a splice, no punctuation runs them together, and a colon does not suit two equal clauses here." },
  { id: "t16rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the new law's burdens fell unequally. ______, large firms absorbed the costs easily while small shops struggled to comply.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The second sentence gives a specific illustration of the unequal burden, so \"Specifically\" fits. \"In contrast\" and \"Nevertheless\" signal opposition, and \"Otherwise\" suggests an alternative." },
  { id: "t16rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying up every thread, the series finale leaves several mysteries ______, inviting fans to debate them for years.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "settled", "trivial", "explained"], correct: 0, explanation: "Declining to tie up threads leaves mysteries \"unresolved.\" \"Settled\" and \"explained\" mean the opposite, and \"trivial\" misdescribes mysteries fans debate for years." },
  { id: "t16rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that his survey reached only one neighborhood, but he argues that the pattern it revealed was so striking that it warrants a citywide study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["He admits a limitation while defending the result's importance.", "He claims his survey covered the whole city.", "He abandons his finding entirely.", "He argues no further study is needed."], correct: 0, explanation: "He concedes the narrow scope yet defends the finding's significance (choice A). B contradicts the concession, C reverses his defense, and D contradicts his call for a citywide study." },
];

// ─────────────────────── PRACTICE TEST 16 · MATH M1 (22) ─────────────────────
const T16_M_M1: SatQuestion[] = [
  { id: "t16m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: isolate x. Subtract 8 from both sides to get 5x = 35. Divide both sides by 5, giving x = 7. Trap: forgetting to subtract 8 first leads to 43/5." },
  { id: "t16m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A printer prints 4 pages every 5 seconds. How many pages does it print in 30 seconds?", type: "mcq", choices: ["24", "20", "28", "30"], correct: 0, explanation: "Goal: scale the rate to 30 seconds. The rate is 4/5 = 0.8 pages per second. Multiply 0.8 × 30 = 24 pages. Trap: dividing 30 by 5 alone gives 6, ignoring the 4 pages per interval." },
  { id: "t16m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² + 2, what is the value of f(4)?", type: "mcq", choices: ["50", "38", "14", "26"], correct: 0, explanation: "Goal: evaluate at x = 4. Square first: 4² = 16. Multiply by 3 to get 48, then add 2, giving 50. Trap: computing (3·4)² = 144 ignores order of operations." },
  { id: "t16m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 18. What is its radius?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the radius from the diameter. The radius is half the diameter, so r = 18 ÷ 2 = 9. Trap: doubling instead of halving would give 36." },
  { id: "t16m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 3x + 5 passes through the point (4, k). What is the value of k?", type: "grid", gridAnswers: ["17"], explanation: "Goal: find y when x = 4. Substitute: k = 3(4) + 5. Compute 3(4) = 12, then add 5 to get k = 17. Trap: adding before multiplying gives 3·9 = 27." },
  { id: "t16m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: solve for x using the mean. Set up (6 + 10 + x)/3 = 9, so 16 + x = 27. Subtract 16 to get x = 11. Trap: dividing 9 by 3 misuses the mean formula." },
  { id: "t16m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 7 = 22, what is the value of x?", type: "mcq", choices: ["5", "15", "29", "7"], correct: 0, explanation: "Goal: isolate x. Subtract 7 from both sides to get 3x = 15. Divide by 3, giving x = 5. Trap: choice B (15) is the value of 3x, not x." },
  { id: "t16m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: add the roots. Factor as (x − 4)(x − 5) = 0, giving roots 4 and 5. Their sum is 4 + 5 = 9, which also equals −b/a = 9. Trap: using the product (20) instead of the sum." },
  { id: "t16m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A jacket's price rose from $40 to $50. What was the percent increase?", type: "mcq", choices: ["25%", "20%", "10%", "125%"], correct: 0, explanation: "Goal: find percent increase. The increase is 50 − 40 = 10. Divide the change by the original: 10/40 = 0.25 = 25%. Trap: dividing by the new price (10/50 = 20%) gives choice B." },
  { id: "t16m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 85°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["50"], explanation: "Goal: use the angle sum of a triangle. The three angles total 180°. Subtract the known angles: 180 − 45 − 85 = 50°. Trap: subtracting from 90 instead of 180 gives a wrong value." },
  { id: "t16m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A gym charges a $25 sign-up fee plus $15 per month. Which equation gives the total cost C for m months?", type: "mcq", choices: ["C = 15m + 25", "C = 25m + 15", "C = 40m", "C = 15m − 25"], correct: 0, explanation: "Goal: model a fixed fee plus a monthly rate. The one-time $25 is the constant and $15 multiplies the months m, giving C = 15m + 25. Trap: choice B swaps which value is multiplied by m." },
  { id: "t16m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 2) = x² + bx − 10, what is the value of b?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the linear coefficient. Expand (x + 5)(x − 2) = x² + 3x − 10 using FOIL: the middle term is 5x − 2x = 3x. So b = 3. Trap: adding 5 and 2 to get 7 ignores the sign on −2." },
  { id: "t16m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 300 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["120", "40", "150", "75"], correct: 0, explanation: "Goal: take 40% of 300. Convert to a decimal: 0.40. Multiply 0.40 × 300 = 120. Trap: choice B (40) reports the percent rather than the count." },
  { id: "t16m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 1) = 3x + 7, what is the value of x?", type: "mcq", choices: ["6", "4", "3", "8"], correct: 0, explanation: "Goal: solve the linear equation. Distribute the 5: 5x − 5 = 3x + 7. Subtract 3x and add 5 to get 2x = 12, so x = 6. Trap: forgetting to distribute the 5 over both terms." },
  { id: "t16m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 9 and width 5. What is its perimeter?", type: "mcq", choices: ["28", "45", "14", "32"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(length + width) = 2(9 + 5). Compute 9 + 5 = 14, then 2 × 14 = 28. Trap: choice B (45) is the area, length × width." },
  { id: "t16m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: equate exponents on base 3. Write 27 as 3³, so 3^(x−1) = 3³ means x − 1 = 3. Add 1 to get x = 4. Trap: setting x − 1 = 27 ignores that 27 must be rewritten as a power of 3." },
  { id: "t16m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "180", "35"], correct: 0, explanation: "Goal: convert map inches to miles. Each inch equals 30 miles, so multiply 5 × 30 = 150 miles. Trap: choice D (35) adds 5 and 30 instead of multiplying." },
  { id: "t16m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find slope from two points. Use (y2 − y1)/(x2 − x1) = (15 − 3)/(6 − 2). That is 12/4 = 3. Trap: inverting the formula to (x2 − x1)/(y2 − y1) gives 1/3." },
  { id: "t16m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 5x − 2, what value of x makes f(x) = 23?", type: "mcq", choices: ["5", "7", "4", "6"], correct: 0, explanation: "Goal: solve 5x − 2 = 23. Add 2 to both sides to get 5x = 25. Divide by 5, giving x = 5. Trap: forgetting to add the 2 back leads to 21/5." },
  { id: "t16m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 8. What is its area, in terms of π?", type: "mcq", choices: ["64π", "16π", "8π", "32π"], correct: 0, explanation: "Goal: use A = πr². Square the radius: 8² = 64. So the area is 64π. Trap: choice B (16π) uses the circumference formula 2πr instead of the area formula." },
  { id: "t16m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 2x + y = 17 and y = 5, what is the value of x?", type: "mcq", choices: ["6", "5", "12", "11"], correct: 0, explanation: "Goal: solve for x by substitution. Replace y with 5: 2x + 5 = 17. Subtract 5 to get 2x = 12, then divide by 2 for x = 6. Trap: choice C (12) is the value of 2x, not x." },
  { id: "t16m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 40-hour week?", type: "grid", gridAnswers: ["880"], explanation: "Goal: multiply rate by hours. Earnings equal 22 × 40. Compute 22 × 40 = 880 dollars. Trap: adding 22 and 40 to get 62 confuses the operation." },
];

// ─────────────────────── PRACTICE TEST 16 · MATH M2 easy (22) ────────────────
const T16_M_M2E: SatQuestion[] = [
  { id: "t16m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 6 = 14, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: find x in x + 6 = 14. The 6 is added to x, so undo it by subtracting 6 from both sides: x + 6 - 6 = 14 - 6, which leaves x = 8. Check: 8 + 6 = 14, matching the equation. Trap: adding 6 to both sides instead of subtracting gives 20, moving in the wrong direction." },
  { id: "t16m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 20% of 80?", type: "mcq", choices: ["16", "20", "40", "8"], correct: 0, explanation: "Goal: compute 20% of 80. Convert the percent to a decimal: 20% = 20/100 = 0.20. Multiply by the whole: 0.20 * 80 = 16. So the answer is 16 (choice A). Check: 10% of 80 is 8, and 20% is double that, 16. Trap: choice B (20) just echoes the percent number; choice C (40) is 50% of 80; choice D (8) is only 10% of 80." },
  { id: "t16m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 8 and a width of 4. What is its area?", type: "grid", gridAnswers: ["32"], explanation: "Goal: find area. Multiply length by width: 8 × 4 = 32. Trap: adding to get a perimeter-style 24 confuses area with perimeter." },
  { id: "t16m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 7x = 56, what is the value of x?", type: "mcq", choices: ["8", "7", "49", "63"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 7, giving x = 56 ÷ 7 = 8. Trap: subtracting 7 from 56 mistakes the operation." },
  { id: "t16m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: apply order of operations. Square first: 5² = 25. Then subtract 4 to get 21. Trap: computing (5 − 4)² = 1 ignores the order of operations." },
  { id: "t16m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 8 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["2/3", "8/12", "1/2", "3/4"], correct: 0, explanation: "Goal: write and simplify the fraction. The team won 8 of 12, so 8/12. Divide top and bottom by 4 to get 2/3. Trap: choice B is correct in value but not in simplest form." },
  { id: "t16m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 5 = 9, what is the value of x?", type: "grid", gridAnswers: ["14"], explanation: "Goal: isolate x. Add 5 to both sides, giving x = 9 + 5 = 14. Trap: subtracting 5 instead of adding gives 4." },
  { id: "t16m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 16, and 20?", type: "mcq", choices: ["16", "48", "18", "14"], correct: 0, explanation: "Goal: compute the mean. Add the three values: 12 + 16 + 20 = 48. Divide by 3 to get 16. Trap: choice B (48) reports the sum, not the average." },
  { id: "t16m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 9. What is its perimeter?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the perimeter of a square. Multiply the side by 4: 4 × 9 = 36. Trap: squaring the side (81) gives the area instead." },
  { id: "t16m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 2x + 3 = 13, what is the value of x?", type: "mcq", choices: ["5", "8", "10", "4"], correct: 0, explanation: "Goal: isolate x. Subtract 3 to get 2x = 10, then divide by 2, giving x = 5. Trap: choice C (10) is the value of 2x, not x." },
  { id: "t16m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 8, what is f(6)?", type: "grid", gridAnswers: ["14"], explanation: "Goal: evaluate the function at 6. Substitute x = 6: f(6) = 6 + 8 = 14. Trap: multiplying 6 by 8 misreads the rule." },
  { id: "t16m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 notebooks for $10. How much do 8 notebooks cost?", type: "mcq", choices: ["$16", "$15", "$13", "$18"], correct: 0, explanation: "Goal: find the unit price, then scale. Each notebook costs $10 ÷ 5 = $2. Multiply $2 × 8 = $16. Trap: adding $10 and 3 extra notebooks without pricing them gives the wrong figure." },
  { id: "t16m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 48, what is the value of x?", type: "mcq", choices: ["8", "6", "42", "54"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 6, giving x = 48 ÷ 6 = 8. Trap: subtracting 6 from 48 mistakes the operation." },
  { id: "t16m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 12 and a height of 5. What is its area?", type: "grid", gridAnswers: ["30"], explanation: "Goal: use the triangle area formula. Area = (1/2)(base)(height) = (1/2)(12)(5). Compute 12 × 5 = 60, then halve to get 30. Trap: forgetting the 1/2 gives 60." },
  { id: "t16m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 64?", type: "mcq", choices: ["16", "32", "8", "25"], correct: 0, explanation: "Goal: take 25% of 64. Since 25% is one quarter, divide 64 by 4 to get 16. Trap: choice B (32) is 50% of 64, not 25%." },
  { id: "t16m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "grid", gridAnswers: ["21"], explanation: "Goal: isolate x. Multiply both sides by 3, giving x = 7 × 3 = 21. Trap: dividing 7 by 3 reverses the needed operation." },
  { id: "t16m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "6", "12"], correct: 0, explanation: "Goal: compute the power. 3³ means 3 × 3 × 3 = 27. Trap: choice B (9) computes only 3² (3 × 3)." },
  { id: "t16m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 90 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["30", "90", "270", "45"], correct: 0, explanation: "Goal: divide distance by time. Speed = 90 ÷ 3 = 30 mph. Trap: multiplying 90 by 3 gives 270, the wrong operation." },
  { id: "t16m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 8 = 12, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: isolate x. Add 8 to both sides to get 4x = 20, then divide by 4, giving x = 5. Trap: dividing 12 by 4 before adding 8 gives a wrong value." },
  { id: "t16m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a diameter of 20. What is its radius?", type: "mcq", choices: ["10", "20", "40", "5"], correct: 0, explanation: "Goal: find the radius. The radius is half the diameter, so 20 ÷ 2 = 10. Trap: choice C (40) doubles instead of halving." },
  { id: "t16m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "2", "5"], correct: 0, explanation: "Goal: substitute and multiply. With x = 5, y = 3 × 5 = 15. Trap: choice B (8) adds 3 and 5 instead of multiplying." },
  { id: "t16m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A box holds 9 green and 6 yellow balls. What fraction of the balls are yellow?", type: "mcq", choices: ["2/5", "6/9", "1/2", "3/5"], correct: 0, explanation: "Goal: find the fraction of yellow balls. There are 6 yellow out of 9 + 6 = 15 total, giving 6/15. Divide top and bottom by 3 for 2/5. Trap: choice B (6/9) uses green, not the total." },
];

// ─────────────────────── PRACTICE TEST 16 · MATH M2 hard (22) ────────────────
const T16_M_M2H: SatQuestion[] = [
  { id: "t16m2h-1", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² − 64 = 0 and x > 0, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: find the positive x satisfying x^2 - 64 = 0. Set up: x^2 - 64 = 0. Add 64 to both sides: x^2 = 64. Take the square root of both sides: x = +sqrt(64) or x = -sqrt(64), giving x = 8 or x = -8. The restriction x > 0 keeps only x = 8. Check: 8^2 - 64 = 64 - 64 = 0, and 8 > 0, so it satisfies both the equation and the condition. Trap: x = -8 also makes x^2 = 64, but it violates x > 0 and must be rejected; reporting -8 ignores the stated restriction." },
  { id: "t16m2h-2", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 4x + 3y = 27 and x − 3y = 3, what is the value of x?", type: "mcq", choices: ["6", "5", "9", "3"], correct: 0, explanation: "Goal: find x from the system 4x + 3y = 27 and x - 3y = 3. The +3y and -3y terms cancel when the equations are added, so add them: (4x + 3y) + (x - 3y) = 27 + 3, which gives 5x = 30. Divide both sides by 5: x = 6. To check, find y: from x - 3y = 3, 6 - 3y = 3, so 3y = 3 and y = 1; then 4(6) + 3(1) = 24 + 3 = 27, matching the first equation. Trap: subtracting the equations instead of adding leaves both x and y terms (3x + 6y = 24) and fails to eliminate y, leading to a wrong value." },
  { id: "t16m2h-3", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 2^x = 64, what is the value of x?", type: "grid", gridAnswers: ["6"], explanation: "Goal: solve 2^x = 64 for x. Rewrite the right side as a power of the same base 2: 64 = 2 * 2 * 2 * 2 * 2 * 2 = 2^6. The equation becomes 2^x = 2^6. With equal bases, the exponents must be equal, so x = 6. Check: 2^6 = 64, which matches. Trap: dividing 64 by 2 to get 32, or otherwise treating the exponent like a coefficient, misunderstands how exponentiation works; the answer comes from counting how many times 2 multiplies to reach 64." },
  { id: "t16m2h-4", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A coat originally priced at $120 is marked up by 15%. What is the new price?", type: "mcq", choices: ["$138", "$135", "$132", "$105"], correct: 0, explanation: "Goal: find the new price after a 15% markup on $120. A markup adds a percentage of the original to the original. Find 15% of 120: 0.15 * 120 = 18. Add this to the original price: 120 + 18 = 138, so the new price is $138 (choice A). Equivalently, multiply by 1.15: 120 * 1.15 = 138, confirming the result. Trap: choice D ($105) subtracts the $18 markup instead of adding it (120 - 15), which would be a discount, not a markup." },
  { id: "t16m2h-5", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A right triangle has legs of length 9 and 12. What is the length of the hypotenuse?", type: "grid", gridAnswers: ["15"], explanation: "Goal: find the hypotenuse of a right triangle with legs 9 and 12. The Pythagorean theorem says leg1^2 + leg2^2 = hypotenuse^2. Substitute: 9^2 + 12^2 = c^2. Compute each square: 81 + 144 = 225, so c^2 = 225. Take the square root: c = sqrt(225) = 15. Check: 9^2 + 12^2 = 81 + 144 = 225 = 15^2, so it works (this is the 3-4-5 triple scaled by 3). Trap: adding the legs directly (9 + 12 = 21) skips the required squaring and square-root steps and overstates the hypotenuse." },
  { id: "t16m2h-6", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If p(x) = 3x − 2, what is the value of p(p(3))?", type: "mcq", choices: ["19", "21", "7", "25"], correct: 0, explanation: "Goal: evaluate the composition p(p(3)) where p(x) = 3x - 2. Work from the inside out. First find the inner value: p(3) = 3(3) - 2 = 9 - 2 = 7. Now apply p to that result: p(7) = 3(7) - 2 = 21 - 2 = 19. So p(p(3)) = 19, which is choice A. Check: inner gives 7, outer gives 3*7 - 2 = 19, consistent. Trap: choice C (7) stops after only the inner application p(3) and forgets to substitute it back into p; choice B (21) computes 3*7 but forgets to subtract 2." },
  { id: "t16m2h-7", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 3x + 4y = 18 and x = y + 1, what is the value of y?", type: "grid", gridAnswers: ["15/7", "2.142857", "2.143"], explanation: "Goal: find y from 3x + 4y = 18 with x = y + 1. Substitute the expression for x into the first equation: 3(y + 1) + 4y = 18. Distribute the 3: 3y + 3 + 4y = 18. Combine like terms: 7y + 3 = 18. Subtract 3 from both sides: 7y = 15. Divide by 7: y = 15/7 (about 2.143). Check: x = y + 1 = 15/7 + 7/7 = 22/7, and 3(22/7) + 4(15/7) = 66/7 + 60/7 = 126/7 = 18, matching. Trap: dropping the +3 when distributing 3(y + 1) gives 7y = 18 and y = 18/7, the wrong value." },
  { id: "t16m2h-8", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "The parabola y = x² − 8x + 7 has its vertex at (h, k). What is the value of h?", type: "grid", gridAnswers: ["4"], explanation: "Goal: find the x-coordinate of the vertex. Use h = −b/(2a) with a = 1 and b = −8, so h = 8/2 = 4. Trap: forgetting the negative sign on b gives −4." },
  { id: "t16m2h-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "In a right triangle, the acute angle θ has cos θ = 5/13. What is sin θ?", type: "mcq", choices: ["12/13", "5/12", "13/12", "13/5"], correct: 0, explanation: "Goal: use a Pythagorean triple. With adjacent 5 and hypotenuse 13, the opposite side is √(13² − 5²) = √144 = 12. So sin θ = opposite/hypotenuse = 12/13. Trap: choice B (5/12) gives tan θ, not sin θ." },
  { id: "t16m2h-10", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If x² + bx + 25 is a perfect square trinomial and b > 0, what is the value of b?", type: "grid", gridAnswers: ["10"], explanation: "Goal: match a perfect square form. A perfect square (x + 5)² = x² + 10x + 25, since 5² = 25. So b = 10. Trap: choice errors come from using 25 directly as b instead of 2·5." },
  { id: "t16m2h-11", section: "math", domain: "Algebra", difficulty: "hard", prompt: "A line has slope −3 and passes through (2, 5). What is its y-intercept?", type: "mcq", choices: ["11", "−1", "5", "8"], correct: 0, explanation: "Goal: solve for b in y = mx + b. Plug in the point: 5 = −3(2) + b, so 5 = −6 + b. Add 6 to get b = 11. Trap: choice B (−1) comes from sign-flipping −6 incorrectly." },
  { id: "t16m2h-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "After a 25% discount, a chair costs $90. What was the original price?", type: "mcq", choices: ["$120", "$112.50", "$115", "$135"], correct: 0, explanation: "Goal: reverse a 25% discount. Paying 75% of the original means 0.75 × original = 90. Divide: 90 ÷ 0.75 = $120. Trap: adding 25% of 90 (choice B-style) wrongly applies the percent to the sale price." },
  { id: "t16m2h-13", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If f(x) = x² and f(a) = 49 with a < 0, what is the value of a?", type: "grid", gridAnswers: ["-7"], explanation: "Goal: solve a² = 49 with a sign condition. The square roots of 49 are ±7. Since a < 0, choose a = −7. Trap: reporting 7 ignores the requirement that a be negative." },
  { id: "t16m2h-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "A cylinder has radius 4 and height 6. What is its volume, in terms of π?", type: "mcq", choices: ["96π", "48π", "24π", "144π"], correct: 0, explanation: "Goal: use V = πr²h. Square the radius: 4² = 16. Multiply by the height: 16 × 6 = 96, so the volume is 96π. Trap: forgetting to square the radius (using 4 × 6) gives 24π." },
  { id: "t16m2h-15", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 1/x + 1/4 = 1, what is the value of x?", type: "grid", gridAnswers: ["4/3", "1.333", "1.3333"], explanation: "Goal: solve for x. Subtract 1/4: 1/x = 1 − 1/4 = 3/4. Take the reciprocal of both sides: x = 4/3. Trap: forgetting to invert leaves x = 3/4 instead of 4/3." },
  { id: "t16m2h-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "What is the product of the solutions to x² − 7x + 10 = 0?", type: "mcq", choices: ["10", "7", "−10", "5"], correct: 0, explanation: "Goal: multiply the roots. Factor as (x − 2)(x − 5) = 0, giving roots 2 and 5. Their product is 2 × 5 = 10, which equals c/a. Trap: choice B (7) uses the sum of the roots instead of the product." },
  { id: "t16m2h-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "The ratio of pens to pencils in a box is 2:7. If there are 36 items total, how many are pencils?", type: "mcq", choices: ["28", "8", "18", "21"], correct: 0, explanation: "Goal: split the total by ratio parts. The parts total 2 + 7 = 9, so each part is 36 ÷ 9 = 4. Pencils take 7 parts: 7 × 4 = 28. Trap: choice B (8) gives the number of pens, not pencils." },
  { id: "t16m2h-18", section: "math", domain: "Geometry and Trigonometry", difficulty: "hard", prompt: "Two similar triangles have a scale factor of 1:4. If the smaller has area 5, what is the area of the larger?", type: "grid", gridAnswers: ["80"], explanation: "Goal: scale area by the square of the linear ratio. The area factor is 4² = 16. Multiply: 5 × 16 = 80. Trap: multiplying by 4 instead of 16 gives 20 and ignores that area scales by the square." },
  { id: "t16m2h-19", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If √(x + 5) = 6, what is the value of x?", type: "grid", gridAnswers: ["31"], explanation: "Goal: remove the square root. Square both sides: x + 5 = 36. Subtract 5 to get x = 31. Trap: forgetting to square the 6 (using 6 directly) gives x = 1." },
  { id: "t16m2h-20", section: "math", domain: "Algebra", difficulty: "hard", prompt: "If 5x − 2y = 19 and y = 3, what is the value of x?", type: "mcq", choices: ["5", "4", "6", "7"], correct: 0, explanation: "Goal: substitute and solve. Replace y with 3: 5x − 6 = 19. Add 6 to get 5x = 25, then divide by 5 for x = 5. Trap: forgetting to add back the 6 leads to 19/5." },
  { id: "t16m2h-21", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If g(x) = x² − 6x + 9, for what value of x does g(x) = 0?", type: "grid", gridAnswers: ["3"], explanation: "Goal: factor and solve. The expression is a perfect square: x² − 6x + 9 = (x − 3)². Set (x − 3)² = 0, so x = 3. Trap: looking for two distinct roots misses that this is a repeated root." },
  { id: "t16m2h-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "hard", prompt: "A population of insects triples every day. If it starts at 20, how many are there after 3 days?", type: "mcq", choices: ["540", "180", "60", "1620"], correct: 0, explanation: "Goal: apply exponential growth. After 3 days the multiplier is 3³ = 27. Multiply: 20 × 27 = 540. Trap: choice C (60) multiplies by 3 only once instead of cubing." },
];

